import numpy as np, itertools
def read(p):
    L=open(p).read().splitlines(); n=int(L[0]); el=[]; co=[]
    for s in L[2:2+n]:
        t=s.split(); el.append(t[0]); co.append([float(x) for x in t[1:4]])
    return el,np.array(co)
el,co=read('opt.xyz'); n=len(el)
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'B':0.84,'Br':1.14,'Ag':1.45}
bonded=set()
for i,j in itertools.combinations(range(n),2):
    if np.linalg.norm(co[i]-co[j]) < cov[el[i]]+cov[el[j]]+0.45: bonded.add((i,j))
def d(i,j): return np.linalg.norm(co[i]-co[j])
# scorpionate = indices 0..44 (B,H,Ag + 3 pz), carbene ligand = 45..75
sc=set(range(0,45)); lig=set(range(45,n))
best=None
for i in sc:
    for j in lig:
        if (i,j) in bonded or (j,i) in bonded: continue
        dd=d(i,j)
        if best is None or dd<best[0]: best=(dd,i,j,el[i],el[j])
print('shortest scorpionate<->carbene-ligand nonbonded:', round(best[0],3), best[3],best[1],'...',best[4],best[2])
# shortest H...H overall (nonbonded)
hh=None
for i,j in itertools.combinations(range(n),2):
    if el[i]=='H' and el[j]=='H' and (i,j) not in bonded:
        dd=d(i,j)
        if hh is None or dd<hh[0]: hh=(dd,i,j)
print('shortest nonbonded H...H:', round(hh[0],3), hh[1], hh[2])
# shortest absolute nonbonded contact overall
mn=None
for i,j in itertools.combinations(range(n),2):
    if (i,j) in bonded: continue
    dd=d(i,j)
    if mn is None or dd<mn[0]: mn=(dd,i,j,el[i],el[j])
print('shortest absolute nonbonded:', round(mn[0],3), mn[3],mn[1],mn[4],mn[2])
